#include <Arduino.h>
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>

// 配線は安全な配置（D4, D5, D6）のままでOK
#define TFT_RST    4   // 基板のD4
#define TFT_DC     5   // 基板のD5
#define TFT_CS     6   // 基板のD6

// ★【最重要】最後の数字に「8000000 (8MHz)」を追加します！
// これによりXIAOがわざとゆっくりデータを送るようになり、液晶が正しく認識できます。
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST, 8000000);

void setup() {
  // Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(2000); 

  Serial.println("Starting LCD with safety speed..."); 

  // 液晶の初期化（もし映らなければここを INITR_GREENTAB や INITR_REDTAB に変えてみてください）
  tft.initR(INITR_BLACKTAB); 

  // 画面を「青色」で塗りつぶす
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          
  tft.setTextColor(ST7735_WHITE); 
  tft.setTextSize(2);             

  // 画面に文字を表示
  tft.println("Hello!");
}

void loop() {
  Serial.println("LCD is working perfectly!");
  delay(2000);
}
